SY=[['希腊 syn-“共同” + bios“生活” → symbios、symbiosis','共同生活的人；共同生活'],['近代生物学采用 symbiosis','不同生物之间密切的共同生活关系']]
MB=B+[['现代 micro-“微小”与生物词族组合','微生物及其群体']]
WD=[
E('symbiosis','英 /ˌsɪmbaɪˈəʊsɪs/；美 /ˌsɪmbaɪˈoʊsɪs/，中间也可读 /bi/','共生；密切而持续的共同生活关系','两种不同生物长期住在一起，彼此的生活联系到了一块。','sym- 是 syn-“共同”在 b 前的形式，-biosis 接“生活”；希腊词本来就是共同生活。',SY,'生物学广义的 symbiosis 可以包括互利、偏利和寄生关系，并非一定双方都获益；也有文献采用较窄的互利义。日常比喻里通常说相互依存、互相有利。阅读专业文章时要看作者怎样定义。','live in symbiosis；a symbiosis between；mutualistic symbiosis。','mutualism 明确说双方获益；symbiosis 重点是密切共同生活，广义用法未必互利。',('The two species live in a form of symbiosis.','这两个物种以一种共生关系共同生活。'),('The museum and the local community developed a productive symbiosis.','博物馆与当地社区形成了富有成效的相互依存关系。'),sources=['https://www.etymonline.com/word/symbiosis','https://openstax.org/books/microbiology/pages/4-1-prokaryote-habitats-relationships-and-microbiomes']),
E('symbiotic','英 /ˌsɪmbaɪˈɒtɪk/；美 /ˌsɪmbaɪˈɑːtɪk/，中间也可读 /bi/','共生的；相互依存的','两个参与者的生活或运作不是完全分开的，而是紧密牵在一起。','与 symbiosis 对应的形容词，接共同生活词族与 -ic 形式。',H(SY,'英语 symbiotic','具有共生关系的'),'a symbiotic relationship 在新闻中常说双方互相帮助或依赖。科学语境中的范围取决于 symbiosis 的定义，不能只看这个形容词就断言双方受益。用到社会关系时，也是在作比喻，不是说两家公司成了一个生物。','a symbiotic relationship；symbiotic bacteria；symbiotic partners。','symbiotic 不等于 identical。两个参与者可以差别很大，却因不同作用而形成密切关系。',('The plant depends on its symbiotic partners for some nutrients.','这种植物依靠共生伙伴获取某些营养。'),('The two organizations have a symbiotic relationship.','这两个组织之间有相互依存的关系。'),sources=['https://www.etymonline.com/word/symbiotic','https://openstax.org/books/biology-2e/pages/45-6-community-ecology']),
E('symbiotically','英 /ˌsɪmbaɪˈɒtɪkli/；美 /ˌsɪmbaɪˈɑːtɪkli/','以共生方式；相互依存地','把“它们有共生关系”改成“它们怎样一起生活、运作”。','symbiotic + -ally，构成描述方式的副词。',H(SY,'英语 symbiotic → symbiotically','共生的 → 以共生方式'),'live symbiotically 描述共同生活的方式；work symbiotically 在比喻中说密切配合。是否双方受益仍取决于上下文，不能用副词词尾改变 symbiosis 本身的定义。','live symbiotically；interact symbiotically；work symbiotically。','symbiotically 强调关系相互联系；independently 强调各自独立完成或存在。',('The organisms live symbiotically within the same habitat.','这些生物在同一生境中以共生方式生活。'),('The two departments work symbiotically on the project.','两个部门在项目中紧密配合、相互依存。'),sources=['https://en.wiktionary.org/wiki/symbiotically','https://www.merriam-webster.com/dictionary/symbiotic']),
E('endosymbiont','美 /ˌendoʊˈsɪmbaɪˌɑːnt/，也读 /ˌendoʊˈsɪmbiˌɑːnt/','内共生生物；生活在宿主体内的共生者','共同生活的伙伴，住到了另一个生物的身体或细胞里面。','endo-“里面” + symbiont“共生者”；-biont 指活着的生物个体。',SY+[['英语 symbiont；endo- + symbiont → endosymbiont','共生者 → 位于宿主体内的共生者']],'endosymbiont 说的是参与这种关系的生物，而不是关系本身。有的住在宿主细胞内，有的处在体内其他位置；具体定义随研究对象而定。内共生关系可以涉及营养、保护等多种作用。','a bacterial endosymbiont；the host and its endosymbiont；intracellular endosymbionts。','endosymbiont 是生物成员；endosymbiosis 是内共生关系或过程。',('The insect carries a bacterial endosymbiont.','这种昆虫体内生活着一种细菌内共生者。'),('The researchers compared the genomes of the host and its endosymbiont.','研究者比较了宿主及其内共生生物的基因组。'),sources=['https://www.merriam-webster.com/dictionary/endosymbiont','https://en.wiktionary.org/wiki/endosymbiont']),
E('endosymbiosis','英 /ˌendəʊˌsɪmbaɪˈəʊsɪs/；美 /ˌendoʊˌsɪmbaɪˈoʊsɪs/','内共生','共同生活不只发生在旁边，也可以发生在另一个生物内部。','endo-“里面” + symbiosis“共同生活、共生”。',H(SY,'英语 endo- + symbiosis → endosymbiosis','发生于宿主体内的共生关系'),'endosymbiosis 可说现存生物体内的共生关系，也在演化讨论中解释某些细胞器的来源。线粒体和叶绿体来自细菌祖先的内共生，是重要例子；这不是说随便吞进一个细胞就会产生新细胞器。','the theory of endosymbiosis；primary endosymbiosis；an endosymbiosis event。','endo- 强调内部；ecto- 强调外部。是否互利以及如何演化，需要另看具体关系。',('Endosymbiosis played an important role in the evolution of eukaryotic cells.','内共生在真核细胞的演化中发挥了重要作用。'),('The lecture explained endosymbiosis using the origin of mitochondria.','讲座以线粒体的起源解释内共生。'),sources=['https://www.merriam-webster.com/dictionary/endosymbiosis','https://openstax.org/books/biology-2e/pages/23-1-eukaryotic-origins']),
E('ectosymbiosis','按构词读法：英 /ˌektəʊˌsɪmbaɪˈəʊsɪs/；美 /ˌektoʊˌsɪmbaɪˈoʊsɪs/','外共生；在宿主表面发生的共生关系','伙伴没有住进细胞内部，而是在宿主的表面生活。','ecto-“外部” + symbiosis“共生”，是与 endosymbiosis 相对的构词。',H(SY,'英语 ecto- + symbiosis → ectosymbiosis','发生在宿主表面等外部界面的共生'),'ectosymbiosis 通常强调共生者位于宿主表面；某些定义也把消化道等与外界连通的表面计入。因此“内外”的边界应按研究使用的定义判断，而不是只看肉眼是否能看到。','a case of ectosymbiosis；ectosymbiosis on the host surface。','ectosymbiosis 不自动等于有益合作；它首先说明共生者所在的位置。',('The study describes ectosymbiosis on the host’s surface.','研究描述了发生在宿主表面的外共生。'),('The chapter compares ectosymbiosis with endosymbiosis.','这一章比较了外共生与内共生。'),sources=['https://en.wiktionary.org/wiki/ectosymbiosis','https://www.merriam-webster.com/dictionary/ectosymbiosis']),
E('symbiology','按构词读法：英 /ˌsɪmbaɪˈɒlədʒi/；美 /ˌsɪmbaɪˈɑːlədʒi/','共生研究；共生学〔少用〕','专门研究不同生物怎样共同生活、怎样相互影响。','以 symbio-“共同生活”与 -logy“研究”组成，可借 symbiosis 理解前半部分。',SY+[['学术组合 symbio- + -logy → symbiology','共生 + 研究 → 共生研究']],'这个少见词指共生关系的研究。更常见的现代写法是 the study of symbiosis 或具体说 symbiosis research。读旧文献或术语表时能认出来即可，不必用它替代一切生态学研究。','research in symbiology；the study of symbiology。','symbiology 讨论生物共生；symbology 通常讨论符号系统。中间多一个 i，就接到了生命词族。',('The old textbook lists symbiology as the study of symbiosis.','旧教材把 symbiology 列为研究共生的学科。'),('The seminar introduced historical questions in symbiology.','研讨课介绍了共生研究史上的一些问题。'),sources=['https://en.wiktionary.org/wiki/symbiology']),
E('symbiogenesis','按构词读法 /ˌsɪmbaɪəʊˈdʒenəsɪs/，美式 /ˌsɪmbaɪoʊˈdʒenəsɪs/','共生发生；通过共生整合产生演化新变化','不同生命原本各自生活，长期结合后形成更紧密的新组织方式。','sym-“共同” + bio-“生命” + genesis“产生”；德语学术词 Symbiogenesis 是命名来源之一。',SY+[['20世纪初德语 Symbiogenesis；英语 symbiogenesis','通过不同生命的共生整合产生新的演化组织']],'symbiogenesis 强调共生结合带来的演化创新，不只是两个生物今天挨在一起。细胞器的共生起源是重要讨论对象；具体过程涉及长期整合、依赖和遗传变化，不能简化成两个个体一碰就合体。','symbiogenesis in evolution；the theory of symbiogenesis；a symbiogenetic origin。','symbiosis 是共生关系；symbiogenesis 进一步关心这种结合怎样参与产生新的演化组织。',('The article examines symbiogenesis in the history of eukaryotes.','文章考察了真核生物演化史中的共生发生。'),('Symbiogenesis emphasizes evolutionary change through biological integration.','共生发生强调通过生物整合产生演化变化。'),sources=['https://en.wiktionary.org/wiki/symbiogenesis','https://www.nature.com/articles/35074092']),
E('microbiome','英 /ˌmaɪkrəʊˈbaɪəʊm/；美 /ˌmaɪkroʊˈbaɪoʊm/','微生物组；某环境中的微生物及其整体系统','把一个环境里的微生物放在一起看，还关心它们携带什么、能做什么、怎样相互作用。','micro-“微小” + biome；也有把 microbiota 与 genome 看作相关混成来源的分析，词义在研究中有不同界定。',MB+[['现代 micro- + biome 等构词分析 → microbiome','微生物群体；或连同其基因、活动环境的整体']],'gut microbiome 常指肠道中的微生物系统。有些文献特别强调其基因集合，另一些把微生物、功能和环境一起纳入；所以不能断言 microbiome 永远只等于“全部基因”。读研究时先看作者的定义。','the gut microbiome；a soil microbiome；microbiome research。','microbiota 通常强调微生物成员；microbiome 常采用更整体的系统或遗传材料视角，但实际用法有重叠。',('The study compared the gut microbiomes of different participants.','研究比较了不同参与者的肠道微生物组。'),('Soil conditions can shape the local microbiome.','土壤条件能够影响当地的微生物组。'),sources=['https://www.merriam-webster.com/dictionary/microbiome','https://pubmed.ncbi.nlm.nih.gov/32605663/']),
E('microbiota','英 /ˌmaɪkrəʊbaɪˈəʊtə/；美 /ˌmaɪkroʊbaɪˈoʊtə/','微生物群；特定环境中的微生物成员','回答的是：在这片皮肤、这段肠道或这团土里，住着哪些微小生物。','micro-“微小” + biota“生物总体”，从全部生物缩小到微生物成员。',MB+[['英语 micro- + biota → microbiota','特定环境中的微生物总体']],'the intestinal microbiota 不是只说一种细菌，而是说肠道的微生物群。不同研究会对纳入的微生物类别作具体界定；它们的组成也会随时间和环境变化，并不是每个人一生不变的一张名单。','gut microbiota；skin microbiota；the composition of the microbiota。','microbiota 说群体成员；a microorganism 说一个微生物个体或一种微生物。',('The researchers analyzed the composition of the skin microbiota.','研究者分析了皮肤微生物群的组成。'),('The team compared the microbiota of roots and leaves.','团队比较了根和叶片上的微生物群。'),sources=['https://www.merriam-webster.com/dictionary/microbiota','https://pubmed.ncbi.nlm.nih.gov/32605663/']),
E('microbiologist','英 /ˌmaɪkrəʊbaɪˈɒlədʒɪst/；美 /ˌmaɪkroʊbaɪˈɑːlədʒɪst/','微生物学家','研究肉眼通常看不清的生命，怎样生活、变化并影响周围环境。','micro-“微小” + biologist“生物学家”；也对应 microbiology 的 -ist 研究者形式。',MB+[['英语 microbiology 与 microbiologist 词族','微生物学；从事微生物研究的人']],'microbiologist 可能研究环境中的微生物，也可能研究食品、工业或疾病相关问题。职业范围远不止“用显微镜看细菌”，还会分析遗传信息、代谢和群落关系。','an environmental microbiologist；a clinical microbiologist；work as a microbiologist。','microbiologist 是微生物研究者；microbiome 是研究对象之一，不能用后者称人。',('The microbiologist studied organisms collected from seawater.','微生物学家研究了从海水中采集的生物。'),('A microbiologist joined the food safety team.','一位微生物学家加入了食品安全团队。'),sources=['https://en.wiktionary.org/wiki/microbiologist','https://www.bls.gov/ooh/life-physical-and-social-science/microbiologists.htm']),
]
